{
  "name": "slow-suite-fixture",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "node --test tests/report.test.mjs"
  }
}

export function reportRows() {
  return [1, 2, 3]
}

import assert from 'node:assert/strict'
import { test } from 'node:test'
import { setTimeout as delay } from 'node:timers/promises'
import { reportRows } from '../src/report.mjs'

async function expensiveFixture() {
  await delay(80)
  return { rows: reportRows() }
}

for (const [name, expected] of [
  ['renders the first row', 1],
  ['renders the second row', 2],
  ['renders the third row', 3],
]) {
  test(name, async () => {
    const fixture = await expensiveFixture()
    assert.equal(fixture.rows.length, 3)
    assert.ok(fixture.rows.includes(expected))
  })
}

{
  "test": "npm run test:contract && npm run test:integration",
  "test:contract": "node --test tests/report.contract.test.mjs",
  "test:integration": "node --test tests/report.integration.test.mjs"
}
